// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const query = input.query || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
const discordUserId = query.discord_user_id;

if (!discordUserId) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le parametre "discord_user_id" est requis'
  };
}

// --- Validation order_id ou order_number ---
const orderId = query.order_id;
const orderNumber = query.order_number;

if (!orderId && !orderNumber) {
  return {
    error: true,
    error_code: 'MISSING_ORDER_ID',
    message: 'Le parametre "order_id" ou "order_number" est requis'
  };
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: discordUserId,
    order_id: orderId,
    order_number: orderNumber,
    project_id: projectId
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Check API errors ---
if (apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'ORDER_NOT_FOUND',
      message: apiResponse.error?.message || 'Commande non trouvee',
      http_status: apiResponse.error?.http_status || 404
    }
  };
}

// --- Format order ---
const order = apiResponse.order || apiResponse;

const totalEuros = (order.total_cents || 0) / 100;
const totalDisplay = totalEuros.toLocaleString('fr-FR', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
}) + ' EUR';

const subtotalEuros = (order.subtotal_cents || 0) / 100;
const subtotalDisplay = subtotalEuros.toLocaleString('fr-FR', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
}) + ' EUR';

// --- Format items ---
const items = (order.items || []).map(item => {
  const itemTotalEuros = (item.total_cents || item.unit_price_cents * item.quantity) / 100;
  return {
    id: item.id,
    product_snapshot: item.product_snapshot,
    quantity: item.quantity,
    unit_price_cents: item.unit_price_cents,
    total_cents: item.total_cents,
    total_display: itemTotalEuros.toLocaleString('fr-FR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }) + ' EUR'
  };
});

// --- Success response ---
return {
  success: true,
  order: {
    id: order.id,
    order_number: order.order_number,
    discord_user_id: order.discord_user_id,
    status: order.status,
    items: items,
    subtotal_cents: order.subtotal_cents,
    subtotal_display: subtotalDisplay,
    discount_cents: order.discount_cents || 0,
    shipping_cents: order.shipping_cents || 0,
    total_cents: order.total_cents,
    total_display: totalDisplay,
    item_count: items.length,
    currency: order.currency || 'EUR',
    coupon_code: order.coupon_code || null,
    customer_email: order.customer_email || null,
    stripe_checkout_session_id: order.stripe_checkout_session_id || null,
    paid_at: order.paid_at || null,
    completed_at: order.completed_at || null,
    created_at: order.created_at
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};
